import{_ as t,o as i,c as n,a2 as s}from"./chunks/framework.CRkDNIZq.js";const m=JSON.parse('{"title":"Technical Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),r={name:"11-glossary.md"};function o(a,e,c,l,g,u){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="technical-glossary" tabindex="-1">Technical Glossary <a class="header-anchor" href="#technical-glossary" aria-label="Permalink to &quot;Technical Glossary&quot;">​</a></h1><ul><li><strong>Metering</strong>: The process of tracking, recording, and attributing real-time resource consumption (API calls, storage, compute seconds) to specific tenants and customers.</li><li><strong>Rating</strong>: The mathematical translation of raw consumption units into monetary currency according to contract rules, pricing tiers, and discounts.</li><li><strong>Idempotency Key</strong>: A unique client-generated token accompanying a request, ensuring that retried network submissions do not cause duplicate processing or double-billing.</li><li><strong>Graduated (Bracket) Pricing</strong>: A tiered pricing structure where usage is sliced across progressive thresholds, with different unit rates applied to each successive volume bracket.</li><li><strong>Volume Pricing</strong>: A pricing model where the total volume achieved over the billing period determines a single discounted rate applied to all consumed units.</li><li><strong>Overage Pricing</strong>: A hybrid model offering a fixed base fee covering an included quantity of units, with excess consumption billed at a specified overage rate.</li><li><strong>Double-Entry Bookkeeping</strong>: An accounting system where every financial transaction consists of at least two entries, guaranteeing that the sum of debits strictly equals the sum of credits.</li><li><strong>Gapless Sequential Numbering</strong>: A legal requirement in fiscal accounting ensuring that invoice numbers follow an unbroken arithmetic sequence (e.g., <code>INV-2026-0001</code>, <code>INV-2026-0002</code>) with no missing numbers.</li><li><strong>Dunning</strong>: The automated process of communicating with customers and scheduling payment retries to collect outstanding balances on past-due invoices.</li><li><strong>Proration</strong>: The proportional allocation of subscription charges or credits based on the exact elapsed time when a customer changes plans mid-cycle.</li><li><strong>Row-Level Security (RLS)</strong>: A database security mechanism restricting data access to rows matching the authenticated tenant&#39;s identity.</li><li><strong>Differential Testing</strong>: A software testing technique where the output of an optimized operational system (e.g. pre-aggregated rollups) is verified against an unoptimized reference implementation (e.g. from-scratch SQL sums).</li><li><strong>MRR (Monthly Recurring Revenue)</strong>: The predictable recurring revenue generated by active customer subscriptions normalized to a monthly interval.</li><li><strong>ARR (Annual Recurring Revenue)</strong>: The annualized value of recurring customer subscriptions ($\\text{MRR} \\times 12$).</li></ul>',2)])])}const h=t(r,[["render",o]]);export{m as __pageData,h as default};
